SELECT COALESCE(SUM(realised_pnl), 0)
FROM realised_pnl_entry
WHERE account_id = #{accountId}

  AND booked_at >= #{from}


  AND booked_at < #{to}

SELECT ticker_symbol, SUM(realised_pnl) AS realised_pnl
FROM realised_pnl_entry
WHERE account_id = #{accountId}

  AND booked_at >= #{from}


  AND booked_at < #{to}

GROUP BY ticker_symbol
ORDER BY ticker_symbol
